//! 🧪️ The actual UI arena owner returns unchanged before converted output or cancellation reaches terminal custody.
use super::*;
use semio_framework_job::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_ui_contract::{OriginalUiValueConversion,UiValue};
#[track_caller]
fn event(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:&mut dyn FnMut(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,|cx|run(cx)));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native UI conversion receipt {p:?}, failure={:?}",result.as_ref().err());result.unwrap()}
#[test]
fn original_ui_value_conversion_preserves_original_arena_owner_and_native_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
 let mut cases=law["cases"].as_array().unwrap().clone();cases.push(serde_json::Value::String(law["wideText"]["repeat"].as_str().unwrap().repeat(law["wideText"]["count"].as_u64().unwrap()as usize)));let mut deep=serde_json::Value::Bool(true);for _ in 0..law["deepListDepth"].as_u64().unwrap(){deep=serde_json::Value::Array(vec![deep])}cases.push(deep);for value in &cases{for cut in law["cancelAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut input=Some(serde_json::from_value::<UiValue>(value.clone()).unwrap());let mut alias=input.as_ref().unwrap().credited_clone().unwrap();let mut owner=None;
  let d=OriginalUiValueConversion::birth_demands();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!OriginalUiValueConversion::admit(&mut input,cx,&mut owner)?);Ok(())});assert!(input.is_some()&&owner.is_none());}event(&mut caller,&mut decoder,g,&mut|cx|{assert!(OriginalUiValueConversion::admit(&mut input,cx,&mut owner)?);Ok(())});assert!(input.is_none());let active=owner.as_mut().unwrap();let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,g,&mut|cx|{assert!(active.advance(&mut input,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());let mut other=None;event(&mut caller,&mut decoder,g,&mut|cx|{assert!(active.advance(&mut other,cx).is_err());Ok(())});
  for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}if active.ready(){break}let Some(d)=active.demands().unwrap()else{continue};for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{active.advance(&mut input,cx)?;Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(active.demands().unwrap(),Some(d));}event(&mut caller,&mut decoder,g,&mut|cx|{active.advance(&mut input,cx)?;Ok(())});assert!(index<262143);}
  let mut output=None;if cut.is_none(){assert!(active.ready());let d=active.take_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!active.take_into(&mut output,cx)?);Ok(())});assert!(output.is_none());}assert_eq!(serde_json::to_value(input.as_ref().unwrap()).unwrap(),*value);event(&mut caller,&mut decoder,g,&mut|cx|{assert!(active.take_into(&mut output,cx)?);Ok(())});assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),*value);}
  for index in 0..262144{if active.terminal_is_empty(){break}let d=active.close_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(&mut input,cx)?;Ok(())}));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.close_demands().unwrap(),d);}event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(&mut input,cx)?;Ok(())}));assert!(index<262143);}assert_eq!(serde_json::to_value(input.as_ref().unwrap()).unwrap(),*value);event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=OriginalUiValueConversion::release_demands();close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();while output.is_some()||!close.is_empty(){event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<semio_framework_value::DslValue>(output.is_some(),&None,32768)?;close_original_retained_step(cx,d,|grant|if output.is_some(){Ok(close.begin_granted(&mut output,grant)?.unwrap())}else{close.select(32768)?.step(grant)})?;Ok(())}));}let mut input=semio_framework_ui_contract::UiValueRetirement::new(input.take().unwrap());while !input.terminal_is_empty(){input.close_step(1,64).unwrap();}let mut alias=semio_framework_ui_contract::UiValueRetirement::new(alias);while !alias.terminal_is_empty(){alias.close_step(1,64).unwrap();}retire_decoder(&mut caller,&mut decoder);caller.retire(g);
 }}
}
